"""80 separately authored synthetic stories; split by story, never by name variant.
Gold labels and supporting-reference labels are never part of requests.
"""
import json
import hashlib
from pathlib import Path


def build():
    cases=[]
    def add(id, split, duplicate, left, right, text=None, history=None, kind='company', support=True):
        facts=[] if text is None else [{'ref':'source_1','text':text,'origin':'synthetic_document','observed_at':'2026-11-01'}]
        cases.append({'id':id,'split':split,'duplicate':duplicate,'kind':kind,
                      'records':[{'id':'r-'+hashlib.sha256((id+'-a').encode()).hexdigest()[:16],**left},{'id':'r-'+hashlib.sha256((id+'-b').encode()).hexdigest()[:16],**right}],
                      'history':history or [[],[]], 'facts':facts,
                      'gold_support':['source_1'] if duplicate and text and support else []})
    def h(field,value,status='superseded'):
        return {'field':field,'value':value,'status':status,'ref':'historical_assertion','observed_at':'2024-01-01'}
    d='development'; t='heldout'
    # DEVELOPMENT: ten positive stories, not ten renamings of a shared fixture.
    add('legal_abbreviation',d,True,{'name':'Copper Harbor Incorporated'},{'name':'Copper Harbor Inc.'},'Registry entry 6104 lists Copper Harbor Incorporated, abbreviated Copper Harbor Inc., as one registration.',[[h('name','Copper Harbor Inc.')],[]])
    add('domain_migration',d,True,{'name':'LedgerNest','website':'https://ledgernest.example'},{'name':'BalanceForge','website':'https://balanceforge.example'},'The filed name-change notice preserves registration 88019 and redirects LedgerNest to BalanceForge.',[[],[h('name','LedgerNest'),h('website','https://ledgernest.example')]])
    add('dual_language',d,True,{'name':'אור כחול','website':'https://blue-light.example'},{'name':'Blue Light Systems','website':'https://blue-light.example'},'Registration 744 publishes the Hebrew name אור כחול and English name Blue Light Systems for the same company.')
    add('person_marriage',d,True,{'name':'Rina Ben Ami','email':'rina@optics.example'},{'name':'Rina Sadeh','email':'rina@optics.example'},'The employee profile states Rina Sadeh previously used the surname Ben Ami.',kind='person')
    add('profile_tracking',d,True,{'name':'Threadline','website':'http://www.threadline.example/','linkedin':'https://www.linkedin.com/company/threadline?utm_source=crm'},{'name':'Threadline Ltd','website':'https://threadline.example','linkedin':'https://linkedin.com/company/threadline'},'The current company registry links this website and this complete company profile to registration 93.')
    add('employee_email_change',d,True,{'name':'Noam Yarden','email':'noam@brightcell.example'},{'name':'N. Yarden','email':'ny@helioframe.example'},'The signed contact update identifies Noam Yarden as the owner of both email addresses after changing jobs.',[[],[h('email','noam@brightcell.example'),h('name','Noam Yarden')]],kind='person')
    add('brand_legal_name',d,True,{'name':'PitchCanvas','website':'https://pitchcanvas.example'},{'name':'Presentation Tools Limited','website':'https://pitchcanvas.example'},'The terms say Presentation Tools Limited trades exclusively as PitchCanvas; both records describe the company, not a separate product.')
    add('history_alias_only',d,True,{'name':'Antimony Analytics'},{'name':'Sb Metrics'},'The filed name change links Antimony Analytics and Sb Metrics under unchanged registration 417.',[[h('name','Sb Metrics')],[]])
    add('same_person_initials',d,True,{'name':'Amir Golan','email':'amir.golan@catalyst.example'},{'name':'A. Golan','email':'amir.golan@catalyst.example'},'An employee directory entry identifies A. Golan as the abbreviation for Amir Golan.',kind='person')
    add('renumbered_phone',d,True,{'name':'CanvasDock','phone':'+1-202-555-0133'},{'name':'CanvasDock','phone':'+1-202-555-0178'},'A customer notice says CanvasDock changed its phone from 0133 to 0178; its company registration was unchanged.',[[],[h('phone','+1-202-555-0133')]])
    # DEVELOPMENT negatives: corrupt exact matches, close names, and uncertain identity.
    add('copied_all_identifiers',d,False,{'name':'Arbor Finance','website':'https://arbor.example','linkedin':'https://linkedin.com/company/arbor'},{'name':'Arbor Finance Services','website':'https://arbor.example','linkedin':'https://linkedin.com/company/arbor'},'Import incident E12 copied the parent website and profile onto a separately registered services subsidiary. The two registration numbers are 810 and 811.')
    add('recycled_domain',d,False,{'name':'Wavelink','website':'https://wavelink.example'},{'name':'Wavelink','website':'https://wavelink.example'},'The 2019 business was dissolved. A different owner registered the expired domain in 2025 for a new corporation, with no legal continuity.')
    add('switchboard',d,False,{'name':'SignalSmith','phone':'+1-202-555-0105'},{'name':'SignalSmith Consulting','phone':'+1-202-555-0105'},'A virtual-office service supplies one receptionist number to many unrelated tenants.')
    add('franchise_units',d,False,{'name':'Bean Circuit Downtown','website':'https://beancircuit.example'},{'name':'Bean Circuit Airport','website':'https://beancircuit.example'},'Workspace records are per franchise operator. The locations are owned by different franchisees with their own registrations.')
    add('fund_and_manager',d,False,{'name':'Radius Ventures I','website':'https://radius.example'},{'name':'Radius Ventures Management','website':'https://radius.example'},'The offering memorandum separates the investment fund from the management company.')
