    add('two_passports',d,False,{'name':'Dana Tal','phone':'+1-202-555-0190'},{'name':'Dana Tal','phone':'+1-202-555-0190'},'A family contact record shares the landline. The two people have different dates of birth and separate passport entries.',kind='person')
