    add('sister_companies',d,False,{'name':'Orbit Health','linkedin':'https://linkedin.com/company/orbit-health'},{'name':'Orbit Medical','linkedin':'https://linkedin.com/company/orbit-medical'},'A holding group lists these as two subsidiaries, not alternative names.')
    add('distinct_query_profiles',d,False,{'name':'Anchor','website':'https://directory.example/company?id=41'},{'name':'Anchor','website':'https://directory.example/company?id=73'},'The directory assigns different registration IDs to these records.')
