    add('provider_login_url',d,False,{'name':'Cairn AI','website':'https://accounts.google.com'},{'name':'Cairn Cloud','website':'https://accounts.google.com'},'The website values are login-provider links, not company websites.')
    add('same_city_common_name',d,False,{'name':'Summit','city':'London'},{'name':'Summit','city':'London'})
    add('regional_legal_entities',d,False,{'name':'Mantle UK','website':'https://mantle.example'},{'name':'Mantle US','website':'https://mantle.example'},'The global brand operates through separately incorporated UK and US entities; the workspace tracks each contracting entity.')
    add('rejected_historical_alias',d,False,{'name':'LatticeRay'},{'name':'RayLattice'},'A human rejected an enrichment claim that these names were aliases.',[[h('name','RayLattice','rejected')],[]])
    add('pending_old_email',d,False,{'name':'Yoni Gal','email':'yoni@one.example'},{'name':'Yoni Gal','email':'yoni@two.example'},'An unreviewed email assertion conflicts with the employee registry. Two current employee IDs exist.',[[],[h('email','yoni@one.example','pending_review')]],kind='person')
    add('investor_email_as_contact',d,False,{'name':'AltaGrid','email':'portfolio@investor.example'},{'name':'AltaGrow','email':'portfolio@investor.example'},'The email is an investor contact reused on two portfolio companies.')
    add('organization_rename_rumor',d,False,{'name':'TempoFrame'},{'name':'TempoWorks'},'An unverified note speculates that TempoWorks might be a new name. No registration, domain or direct identity link supports it.')
    add('distinct_uuid_profile',d,False,{'name':'MergeTest','website':'https://profiles.example/u/aa11'},{'name':'MergeTest','website':'https://profiles.example/u/bb22'})
    # HELDOUT positives: separately authored evidence patterns, frozen before any model run.
    add('statutory_conversion',t,True,{'name':'Mistral Robotics LLC','website':'https://mistralrobotics.example'},{'name':'Mistral Robotics Inc','website':'https://mistralrobotics.example'},'A conversion certificate states the LLC continued as the corporation with all obligations intact; this was not an asset sale.',[[],[h('name','Mistral Robotics LLC')]])
    add('two_step_name_change',t,True,{'name':'QuartzTrail','website':'https://quartztrail.example'},{'name':'Waypoint Intelligence','website':'https://waypoint-intelligence.example'},'Registration 590 changed name from QuartzTrail to FieldAtlas in 2022 and then to Waypoint Intelligence in 2025.',[[],[h('name','QuartzTrail'),h('name','FieldAtlas'),h('website','https://quartztrail.example')]])
    add('person_diacritic',t,True,{'name':'Léa Ben-David','email':'lea@kinetic.example'},{'name':'Lea Ben David','email':'lea@kinetic.example'},'The same verified employee account lists both accent and spacing variants as display names.',kind='person')
    add('company_punctuation',t,True,{'name':'O.R.B.I.T. Research','website':'https://orbit-research.example','linkedin':'https://linkedin.com/company/orbit-research'},{'name':'Orbit Research','website':'https://orbit-research.example/','linkedin':'https://linkedin.com/company/orbit-research'},'A registry filing identifies the dotted spelling as a stylized trading name of Orbit Research.')
    add('personal_to_work_email',t,True,{'name':'Tamar Nir','email':'tamar.nir@personal.example'},{'name':'Tamar N.','email':'tnir@cobalt.example'},'A signed message gives Tamar Nir’s former personal and current work addresses as her own.',[[h('email','tnir@cobalt.example')],[]],kind='person')
    add('bilingual_registration',t,True,{'name':'שביל חכם בעמ'},{'name':'Smart Path Ltd'},'Registry number 552108 is printed beside both the Hebrew legal name שביל חכם and its English name Smart Path Ltd.',[[h('name','Smart Path Ltd')],[]])
    add('domain_tracking_variants',t,True,{'name':'Mossline','website':'https://WWW.mossline.example/?utm_campaign=q4','linkedin':'https://linkedin.com/company/mossline?trk=public_profile'},{'name':'Mossline Technologies','website':'http://mossline.example','linkedin':'https://linkedin.com/company/mossline'},'The company registry links Mossline Technologies to the Mossline brand and these identity URLs.')
    add('legal_to_trade_history',t,True,{'name':'Harbor 2020 Holdings'},{'name':'TidePilot'},'An unchanged registration certificate records Harbor 2020 Holdings as the legal name and TidePilot as its only trading name.',[[],[h('name','Harbor 2020 Holdings')]])
    add('former_domain_two_languages',t,True,{'name':'Nitzan Sensors','website':'https://nitzan-sensors.example'},{'name':'ניצן חיישנים','website':'https://sprout-sensing.example'},'The bilingual company notice identifies sprout-sensing.example as the replacement domain for the same Nitzan Sensors business.',[[],[h('website','https://nitzan-sensors.example'),h('name','Nitzan Sensors')]])
    add('branch_same_entity_granularity',t,True,{'name':'Fathom Instruments — Sales','website':'https://fathom-instruments.example'},{'name':'Fathom Instruments','website':'https://fathom-instruments.example'},'Sales is an internal department, not incorporated separately. This workspace keeps one record per legal company; the department record is another entry for that company.')
    # HELDOUT negatives: no name substitutions of development fixtures.
    add('asset_sale_without_continuity',t,False,{'name':'EchoPilot','website':'https://echopilot.example','linkedin':'https://linkedin.com/company/echopilot'},{'name':'EchoPilot Technologies','website':'https://echopilot.example','linkedin':'https://linkedin.com/company/echopilot'},'A bankruptcy auction transferred trademarks, the domain and social account to a newly incorporated buyer; the seller’s legal entity was not acquired.')
    add('two_registrations_same_brand',t,False,{'name':'Fernhouse','website':'https://fernhouse.example','linkedin':'https://linkedin.com/company/fernhouse'},{'name':'Fernhouse','website':'https://fernhouse.example','linkedin':'https://linkedin.com/company/fernhouse'},'The signed contracts identify separate contracting companies: registration IL-730 and US-913. The workspace records contracting entities, not the shared brand.')
    add('stale_site_and_profile',t,False,{'name':'Oakshift','website':'https://oakshift.example','linkedin':'https://linkedin.com/company/oakshift'},{'name':'Oakshore','website':'https://oakshift.example','linkedin':'https://linkedin.com/company/oakshift'},'Both identifiers on Oakshore were filled by a name-similarity enrichment. No independent source supports those values; a customer ticket reports the match is wrong.')
    add('shared_domain_business_units',t,False,{'name':'Junco Aviation Leasing','website':'https://junco.example'},{'name':'Junco Aviation Operations','website':'https://junco.example'},'The annual report distinguishes the asset-owning lessor and the licensed operator with their own registrations.')
    add('identical_name_birthdates',t,False,{'name':'Omer Katz'},{'name':'Omer Katz'},'Attendee 211 was born in 1984 and attendee 708 in 1997; both signed into the same event.',kind='person')
    add('generic_catchall_email',t,False,{'name':'Tessera Audio','email':'unknown@placeholder.example'},{'name':'Tessera Sound','email':'unknown@placeholder.example'},'The CRM importer uses this email as its missing-value placeholder, not a mailbox belonging to either company.')
    add('unrelated_redirect',t,False,{'name':'Paperfin','website':'https://paperfin.example'},{'name':'Paperfin Ventures','website':'https://paperfin-ventures.example'},'A parked-domain broker redirects paperfin.example to its buyer lead form at paperfin-ventures.example. No legal-entity continuity is stated.')
    add('fund_vintages',t,False,{'name':'Heliotrope Fund II','website':'https://heliotrope.example'},{'name':'Heliotrope Fund III','website':'https://heliotrope.example'},'The subscription documents establish different limited partnerships for the two fund vintages.')
    add('person_roles_same_company',t,False,{'name':'Adi Bar','email':'ceo@lumenfold.example'},{'name':'Dorit Bar','email':'ceo@lumenfold.example'},'Dorit took over as CEO from Adi; the role mailbox stayed the same. Both people remain on the board.',kind='person')
